import { IndividualSimUI } from '../../individual_sim_ui';
import { Database } from '../../proto_utils/database';
import { SimResult } from '../../proto_utils/sim_result';
import { isHealingSpec } from '../../proto_utils/utils';
import { classTalentsConfig } from '../../talents/factory';
import { TypedEvent } from '../../typed_event';
import { Component } from '../component';
import { CopyButton } from '../copy_button';
import { IndividualLinkExporter } from '../exporters';
import { IndividualLinkImporter } from '../importers';

const HISTORY_STORAGE_KEY = '__simHistory__';
const MAX_HISTORY_ENTRIES = 50;

// Settings captured when a sim is started, so later edits made while it runs don't leak in.
export interface SimHistorySnapshot {
	time: number;
	specName: string;
	talentPoints: string;
	// Same encoding as the hash of a sharable link (link export categories).
	settings: string;
}

interface SimHistoryEntry extends SimHistorySnapshot {
	avg: number;
	stdev: number;
	min: number;
	max: number;
	iterations: number;
	duration: number;
	durationVariation: number;
	// Health-based fights have no fixed duration, so `duration` holds the average iteration length.
	healthBased: boolean;
}

// List of previous 'Simulate' runs for this spec, kept in local storage.
export class SimHistory extends Component {
	private readonly simUI: IndividualSimUI<any>;
	private readonly storageKey: string;
	private readonly metricName: string;

	private readonly countElem: HTMLElement;
	private readonly clearButton: HTMLButtonElement;
	private readonly tableElem: HTMLTableElement;
	private readonly bodyElem: HTMLTableSectionElement;
	private readonly emptyElem: HTMLElement;

	constructor(parent: HTMLElement, simUI: IndividualSimUI<any>) {
		super(parent, 'sim-history-root');
		this.simUI = simUI;
		this.storageKey = simUI.getStorageKey(HISTORY_STORAGE_KEY);
		this.metricName = isHealingSpec(simUI.player.spec) ? 'HPS' : 'DPS';

		this.rootElem.innerHTML = `
			<div class="sim-history-header">
				<span class="sim-history-count"></span>
				<button class="btn btn-sm btn-outline-danger sim-history-clear">
					<i class="fas fa-trash me-1"></i>Clear history
				</button>
			</div>
			<table class="sim-history-table">
				<thead>
					<tr>
						<th></th>
						<th>${this.metricName}</th>
						<th>Std Dev</th>
						<th>Min - Max</th>
						<th>Spec</th>
						<th>Duration</th>
						<th>Iterations</th>
						<th>Time</th>
						<th></th>
					</tr>
				</thead>
				<tbody></tbody>
			</table>
			<div class="sim-history-empty">
				No sims yet. Every run of <b>Simulate</b> is saved here.
			</div>
		`;
		this.countElem = this.rootElem.querySelector('.sim-history-count') as HTMLElement;
		this.clearButton = this.rootElem.querySelector('.sim-history-clear') as HTMLButtonElement;
		this.tableElem = this.rootElem.querySelector('.sim-history-table') as HTMLTableElement;
		this.bodyElem = this.tableElem.querySelector('tbody') as HTMLTableSectionElement;
		this.emptyElem = this.rootElem.querySelector('.sim-history-empty') as HTMLElement;

		this.clearButton.addEventListener('click', () => {
			if (window.confirm('Delete all saved sims for this spec?')) {
				this.saveEntries([]);
				this.render();
			}
		});

		// Keep in sync with sims run from other browser tabs.
		window.addEventListener('storage', event => {
			if (event.key == this.storageKey) {
				this.render();
			}
		});

		this.render();
	}

	takeSnapshot(): SimHistorySnapshot {
		const { specName, talentPoints } = this.getSpecInfo();
		return {
			time: Date.now(),
			specName: specName,
			talentPoints: talentPoints,
			settings: IndividualLinkExporter.encodeSettings(this.simUI.toProto(IndividualLinkImporter.DEFAULT_CATEGORIES)),
		};
	}

	addResult(snapshot: SimHistorySnapshot, simResult: SimResult) {
		const player = simResult.getPlayers()[0];
		if (!player) {
			return;
		}
		const metrics = this.metricName == 'HPS' ? player.hps : player.dps;
		const encounter = simResult.request.encounter;
		const healthBased = !!encounter?.useHealth;

		const entry: SimHistoryEntry = {
			...snapshot,
			avg: metrics.avg,
			stdev: metrics.stdev,
			min: metrics.min,
			max: metrics.max,
			iterations: simResult.iterations,
			duration: healthBased ? simResult.result.avgIterationDuration : encounter?.duration || 0,
			durationVariation: healthBased ? 0 : encounter?.durationVariation || 0,
			healthBased: healthBased,
		};

		this.saveEntries([entry].concat(this.loadEntries()).slice(0, MAX_HISTORY_ENTRIES));
		this.render();
	}

	// Names the spec after the talent tree with the most points, e.g. 'Fire' and '18/53/0'.
	private getSpecInfo(): { specName: string; talentPoints: string } {
		const trees = classTalentsConfig[this.simUI.player.getClass()] || [];
		const points = this.simUI.player
			.getTalentsString()
			.split('-')
			.map(tree => tree.split('').reduce((sum, digit) => sum + (parseInt(digit) || 0), 0));
		while (points.length < trees.length) {
			points.push(0);
		}

		const maxPoints = Math.max(0, ...points);
		const specName = maxPoints > 0 ? trees[points.indexOf(maxPoints)]?.name ?? '' : '';
		return { specName: specName, talentPoints: points.join('/') };
	}

	private async loadEntry(entry: SimHistoryEntry) {
		const settings = IndividualLinkImporter.decodeSettings(entry.settings);
		if (settings.player?.equipment) {
			await Database.loadLeftoversIfNecessary(settings.player.equipment);
		}
		this.simUI.fromProto(TypedEvent.nextEventID(), settings, IndividualLinkImporter.DEFAULT_CATEGORIES);
	}

	private makeLink(entry: SimHistoryEntry): string {
		const linkUrl = new URL(window.location.href);
		linkUrl.hash = entry.settings;
		linkUrl.searchParams.delete(IndividualLinkImporter.CATEGORY_PARAM);
		return linkUrl.toString();
	}

	private render() {
		const entries = this.loadEntries();

		this.countElem.textContent = entries.length
			? `${entries.length} saved sim${entries.length == 1 ? '' : 's'} (up to ${MAX_HISTORY_ENTRIES})`
			: '';
		this.clearButton.classList.toggle('hide', entries.length == 0);
		this.tableElem.classList.toggle('hide', entries.length == 0);
		this.emptyElem.classList.toggle('hide', entries.length > 0);

		this.bodyElem.innerHTML = '';
		entries.forEach((entry, i) => this.bodyElem.appendChild(this.buildRow(entry, i)));
	}

	private buildRow(entry: SimHistoryEntry, index: number): HTMLTableRowElement {
		const row = document.createElement('tr');
		const duration = entry.healthBased
			? `~${entry.duration.toFixed(0)}s <span class="sim-history-muted">(health)</span>`
			: `${entry.duration.toFixed(0)}s${
					entry.durationVariation ? ` <span class="sim-history-muted">±${entry.durationVariation.toFixed(0)}</span>` : ''
			  }`;

		row.innerHTML = `
			<td class="sim-history-actions"></td>
			<td class="sim-history-avg">${entry.avg.toFixed(2)}</td>
			<td>±${entry.stdev.toFixed(0)}</td>
			<td>${entry.min.toFixed(0)} - ${entry.max.toFixed(0)}</td>
			<td>${entry.specName || '-'} <span class="sim-history-muted">(${entry.talentPoints})</span></td>
			<td>${duration}</td>
			<td>${entry.iterations}</td>
			<td>${formatTime(entry.time)}</td>
			<td>
				<a href="javascript:void(0)" class="sim-history-delete link-danger" role="button" title="Remove from history">
					<i class="fa fa-times"></i>
				</a>
			</td>
		`;

		const actionsCell = row.querySelector('.sim-history-actions') as HTMLElement;

		const loadButton = document.createElement('button');
		loadButton.classList.add('btn', 'btn-primary', 'btn-sm', 'me-2');
		loadButton.innerHTML = '<i class="fas fa-upload me-1"></i>Load profile';
		loadButton.addEventListener('click', async () => {
			try {
				await this.loadEntry(entry);
				loadButton.innerHTML = '<i class="fas fa-check me-1"></i>Loaded';
				setTimeout(() => (loadButton.innerHTML = '<i class="fas fa-upload me-1"></i>Load profile'), 1500);
			} catch (e) {
				alert('Failed to load this sim: ' + e);
			}
		});
		actionsCell.appendChild(loadButton);

		new CopyButton(actionsCell, {
			extraCssClasses: ['btn-outline-primary', 'btn-sm'],
			getContent: () => this.makeLink(entry),
			text: 'Copy link',
		});

		row.querySelector('.sim-history-delete')!.addEventListener('click', () => {
			const entries = this.loadEntries();
			entries.splice(index, 1);
			this.saveEntries(entries);
			this.render();
		});

		return row;
	}

	private loadEntries(): Array<SimHistoryEntry> {
		try {
			const entries = JSON.parse(window.localStorage.getItem(this.storageKey) || '[]');
			return Array.isArray(entries) ? entries : [];
		} catch (e) {
			return [];
		}
	}

	private saveEntries(entries: Array<SimHistoryEntry>) {
		// If storage is full, drop the oldest sims until it fits.
		while (true) {
			try {
				window.localStorage.setItem(this.storageKey, JSON.stringify(entries));
				return;
			} catch (e) {
				if (entries.length == 0) {
					console.warn('Failed to save sim history: ' + e);
					return;
				}
				entries = entries.slice(0, -1);
			}
		}
	}
}

function formatTime(time: number): string {
	const date = new Date(time);
	const timeStr = date.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit', second: '2-digit' });
	if (date.toDateString() == new Date().toDateString()) {
		return timeStr;
	}
	return `${date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}, ${timeStr}`;
}
