import { Tooltip } from 'bootstrap';
// eslint-disable-next-line @typescript-eslint/no-unused-vars
import { element, fragment } from 'tsx-vanilla';

import { Player } from '../player.js';
import { ItemSlot, Spec } from '../proto/common.js';
import { SimUI } from '../sim_ui.js';
import { EventID, TypedEvent } from '../typed_event.js';
import { BooleanPicker } from './boolean_picker.js';
import { Component } from './component.js';
import { IconRelicSwapPicker } from './gear_picker.js';
import { Input } from './input.js';
import { NumberPicker } from './number_picker.js';

export interface RelicSwapConfig {
	itemSlots: Array<ItemSlot>;
	note?: string;
}

// Widget for swapping the relic slot (idol / libram / totem / sigil). Separate from the
// weapon ItemSwapPicker: it drives the Player's relic swap set and exposes the swap reaction
// time used by the in-combat relic swap GCD model.
export class RelicSwapPicker<SpecType extends Spec> extends Component {
	private readonly itemSlots: Array<ItemSlot>;

	constructor(parentElem: HTMLElement, simUI: SimUI, player: Player<SpecType>, config: RelicSwapConfig) {
		super(parentElem, 'item-swap-picker-root');
		this.itemSlots = config.itemSlots;

		new BooleanPicker(this.rootElem, player, {
			reverse: true,
			label: 'Enable Ranged Slot Swapping',
			labelTooltip:
				'Allows configuring a Ranged Slot Swap Set (idol / libram / totem / sigil) which is used with the <b>Ranged Slot Swap</b> APL action. The previous item\'s effect is removed and the new one applied on swap.',
			extraCssClasses: ['input-inline'],
			getValue: (player: Player<SpecType>) => player.getEnableRelicSwap(),
			setValue(eventID: EventID, player: Player<SpecType>, newValue: boolean) {
				player.setEnableRelicSwap(eventID, newValue);
			},
			changedEvent: (player: Player<SpecType>) => player.relicSwapChangeEmitter,
		});

		const swapPickerContainer = document.createElement('div');
		swapPickerContainer.classList.add('input-root', 'input-inline');
		this.rootElem.appendChild(swapPickerContainer);

		let noteElem: Element;
		if (config.note) {
			noteElem = this.rootElem.appendChild(<p className="form-text">{config.note}</p>);
		}

		// Reaction-time field driving the in-combat relic swap GCD model. Kept on its own row
		// (outside the inline relic-swap row) so it doesn't overlap the relic icon.
		const reactionTimeContainer = document.createElement('div');
		reactionTimeContainer.classList.add('input-root');
		this.rootElem.appendChild(reactionTimeContainer);
		new NumberPicker(reactionTimeContainer, player, {
			label: 'Swap Reaction Time',
			labelTooltip:
				'Player reaction time (0-300ms) added on top of a ranged slot swap that is performed while already mid-GCD. A fresh swap instead costs a full swap GCD.',
			changedEvent: (player: Player<SpecType>) => player.miscOptionsChangeEmitter,
			getValue: (player: Player<SpecType>) => player.getSwapReactionTime(),
			setValue: (eventID: EventID, player: Player<SpecType>, newValue: number) => {
				player.setSwapReactionTime(eventID, Math.max(0, Math.min(300, newValue)));
			},
		});

		const toggleEnabled = () => {
			if (!player.getEnableRelicSwap()) {
				swapPickerContainer.classList.add('hide');
				reactionTimeContainer.classList.add('hide');
				noteElem?.classList.add('hide');
			} else {
				swapPickerContainer.classList.remove('hide');
				reactionTimeContainer.classList.remove('hide');
				noteElem?.classList.remove('hide');
			}
		};
		player.relicSwapChangeEmitter.on(toggleEnabled);
		toggleEnabled();

		const label = document.createElement('label');
		label.classList.add('form-label');
		label.textContent = 'Ranged Slot Swap';
		swapPickerContainer.appendChild(label);

		const itemSwapContainer = Input.newGroupContainer();
		itemSwapContainer.classList.add('icon-group');
		swapPickerContainer.appendChild(itemSwapContainer);

		const swapButtonFragment = document.createElement('fragment');
		swapButtonFragment.innerHTML = `
			<a
				href="javascript:void(0)"
				class="gear-swap-icon"
				role="button"
				data-bs-title="Swap with equipped ranged slot item"
			>
				<i class="fas fa-arrows-rotate me-1"></i>
			</a>
		`;

		const swapButton = swapButtonFragment.children[0] as HTMLElement;
		itemSwapContainer.appendChild(swapButton);

		swapButton.addEventListener('click', _event => this.swapWithGear(TypedEvent.nextEventID(), player));
		Tooltip.getOrCreateInstance(swapButton);

		this.itemSlots.forEach(itemSlot => {
			new IconRelicSwapPicker(itemSwapContainer, simUI, player, itemSlot);
		});
	}

	swapWithGear(eventID: EventID, player: Player<SpecType>) {
		let newGear = player.getGear();
		let newRsg = player.getRelicSwapGear();

		this.itemSlots.forEach(slot => {
			const gearItem = player.getGear().getEquippedItem(slot);
			const swapItem = player.getRelicSwapGear().getEquippedItem(slot);

			newGear = newGear.withEquippedItem(slot, swapItem, player.canDualWield2H());
			newRsg = newRsg.withEquippedItem(slot, gearItem, player.canDualWield2H());
		});

		TypedEvent.freezeAllAndDo(() => {
			player.setGear(eventID, newGear);
			player.setRelicSwapGear(eventID, newRsg);
		});
	}
}
